package chatui

const ChatsaveStyles = `.chatsave-bookmark{width:16px;height:16px;flex:none}.menu-item.chatsave-action{min-height:44px;white-space:normal}.chatsave-action[aria-pressed="true"]{color:var(--hcm-color-brand-primary)}.chatsave-action[aria-pressed="true"] .chatsave-bookmark{fill:currentColor}.menu-item.chatsave-action[aria-pressed="true"]{color:var(--hcm-color-text)}@media (pointer:coarse){.message-action.chatsave-action{min-width:44px;min-height:44px}}.chatsave-panel{position:fixed;z-index:1500;inset-block-start:var(--chatsave-top,82px);inset-block-end:0;inset-inline-start:auto;inset-inline-end:0;width:min(var(--chat-details,400px),100vw);height:auto;max-width:calc(100vw - 16px);margin:0;overflow:auto;box-sizing:border-box;border:0;border-inline-start:1px solid var(--line);background:var(--canvas);color:var(--hcm-color-text)}.chat-workspace:has(>.chatsave-panel:popover-open) .chat-layout{grid-template-columns:minmax(220px,var(--chat-rail)) minmax(0,1fr) minmax(260px,var(--chat-details))}.chatsave-content :focus-visible,.chatsave-sidebar>summary:focus-visible,.chatsave-action:focus-visible{outline:3px solid var(--hcm-color-brand-primary);outline-offset:2px}@media(max-width:760px){.chat-workspace:has(>.chatsave-panel:popover-open) .chat-layout{grid-template-columns:minmax(0,1fr)}}@media(prefers-reduced-motion:reduce){.chatsave-panel *{animation:none!important;transition:none!important}}.agent-icon-pending{background:var(--soft);border-radius:50%}.chat-row-name.agent-name-pending{display:block;max-width:96px;min-height:1em;border-radius:var(--hcm-radius-control);background:var(--soft)}`

const ChatsaveSidebarStyles = `.chatsave-sidebar>summary{list-style:none;background:transparent;border:0;border-radius:var(--hcm-radius-control);color:var(--muted);cursor:pointer}.chatsave-sidebar>summary::-webkit-details-marker{display:none}.chatsave-sidebar>summary:hover,.chatsave-sidebar>summary:focus-visible{background:var(--soft);color:var(--ink)}.chatsave-sidebar[open]>summary{background:var(--soft);color:var(--accent);font-weight:650}.chatsave-sidebar>summary .chat-badge{position:static;flex:none;margin:0}`
